<script setup>
import $ from 'jquery'
import { onMounted, ref, computed } from "vue" // Добавлены ref и computed

import { useGsapOrchestrator } from '@/composables/useGsapOrchestrator'
import { getFaqAnimations } from '@/components/blocks/general/section/faq.animations.js'

const faqSection = ref(null)
const phone = ref(null)
const l_man = ref(null)
const r_man = ref(null)
const proto = ref(null)

const animConfig = computed(() => getFaqAnimations({
  faqSection: faqSection.value,
  phone: phone.value,
  l_man: l_man.value,
  r_man: r_man.value,
  proto: proto.value
}))

useGsapOrchestrator(faqSection, animConfig)

onMounted( () => {
  $('.accordion').find('.accordion-title').on('click', function(){
    // Adds Active Class
    $(this).toggleClass('active');
    // Expand or Collapse This Panel
    $(this).next().slideToggle('slow');
    // Hide The Other Panels
    $('.accordion-content').not($(this).next()).slideUp('slow');
    // Removes Active Class From Other Titles
    $('.accordion-title').not($(this)).removeClass('active');
  });
})
const props = defineProps({
  list: {
    type: Object,
    required: true
  },
})
</script>

